Item.method_code:
const state = options.getState();
const selectedRows = state.grid.selectedRows;
const configId = options.rows.get(selectedRows[0], 'config_id');
const props = options.getProps();
const selectedFavorite = options.favorites.filterFavorites(
	props.favorites,
	'Item',
	(favorite) => favorite.additional_data.id === configId
)[0];

if (selectedFavorite) {
	const { openFavoriteDialog } = aras.getMainWindow().ArasCore.Dialogs;
	return openFavoriteDialog(selectedFavorite);
}
